<?php require 'header.php';$p=db();$id=(int)($_GET['id']??0);$t=[];if($id){$st=$p->prepare('SELECT * FROM tasks WHERE id=?');$st->execute([$id]);$t=$st->fetch()?:[];if(!$t){http_response_code(404);die('Tarea no encontrada');}if(!user_can_edit_task($t)){http_response_code(403);die('Solo puede modificar las fechas de tareas creadas por usted.');}}
$requestedLevel=$_GET['level']??($t['level']??'PROCESO');$requestedParent=$_GET['parent']??($t['parent_code']??'');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{
 if($id && !admin()){
   $newStart=($_POST['start_date']??'')?:null;$newEnd=($_POST['end_date']??'')?:null;$reason=trim($_POST['extension_reason']??'');$oldStart=$t['start_date']?:null;$oldEnd=$t['end_date']?:null;
   if($newStart!==$oldStart || $newEnd!==$oldEnd){if($reason==='')throw new RuntimeException('Debe indicar el motivo del cambio de plazo.');$p->beginTransaction();$p->prepare('INSERT INTO task_date_history(task_id,old_start_date,new_start_date,old_end_date,new_end_date,reason,changed_by) VALUES(?,?,?,?,?,?,?)')->execute([$id,$oldStart,$newStart,$oldEnd,$newEnd,$reason,current_user_id()]);$p->prepare('UPDATE tasks SET start_date=?,end_date=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$newStart,$newEnd,current_user_id(),$id]);$p->commit();audit('CAMBIO_PLAZO',$t['code'].' · '.$oldStart.' / '.$oldEnd.' → '.$newStart.' / '.$newEnd.' · '.$reason);}
 } else {
   $f=['code','level','parent_code','area','project','task','responsible','priority','status','start_date','end_date','dependency','purchase_milestone','reference_no','amount','provider','next_milestone','next_date','risk'];$v=[];foreach($f as $x)$v[$x]=trim((string)($_POST[$x]??''));$v['parent_code']=$v['level']==='PROCESO'?null:($v['parent_code']?:null);$v['amount']=$v['amount']===''?null:(float)$v['amount'];
   if($id){$oldStart=$t['start_date']?:null;$oldEnd=$t['end_date']?:null;$newStart=$v['start_date']?:null;$newEnd=$v['end_date']?:null;$reason=trim($_POST['extension_reason']??'');$p->beginTransaction();if($newStart!==$oldStart||$newEnd!==$oldEnd){if($reason==='')throw new RuntimeException('Debe indicar el motivo del cambio de plazo.');$p->prepare('INSERT INTO task_date_history(task_id,old_start_date,new_start_date,old_end_date,new_end_date,reason,changed_by) VALUES(?,?,?,?,?,?,?)')->execute([$id,$oldStart,$newStart,$oldEnd,$newEnd,$reason,current_user_id()]);}$set=implode(',',array_map(fn($x)=>"$x=:$x",$f));$v['id']=$id;$v['updated_by']=current_user_id();$p->prepare("UPDATE tasks SET $set,updated_by=:updated_by,updated_at=CURRENT_TIMESTAMP WHERE id=:id")->execute($v);$p->commit();audit('EDITAR_TAREA',$v['code']);}
   else{$cols=implode(',',$f);$marks=':'.implode(',:',$f);$v['created_by']=current_user_id();$v['updated_by']=current_user_id();$p->prepare("INSERT INTO tasks($cols,created_by,updated_by,original_start_date,original_end_date) VALUES($marks,:created_by,:updated_by,:start_date,:end_date)")->execute($v);audit('CREAR_TAREA',$v['code']);}
 }
 header('Location:tasks.php');exit;
}catch(Throwable $e){if($p->inTransaction())$p->rollBack();$error=$e->getMessage();}}
$processes=$p->query("SELECT code,task FROM tasks WHERE level='PROCESO' ORDER BY code")->fetchAll();$hist=[];if($id){$st=$p->prepare('SELECT h.*,u.name FROM task_date_history h LEFT JOIN users u ON u.id=h.changed_by WHERE h.task_id=? ORDER BY h.id DESC');$st->execute([$id]);$hist=$st->fetchAll();}$limited=$id&&!admin();
?>
<div class="page-title"><div><h1><?=$id?'Editar tarea':($requestedLevel==='ETAPA'?'Nueva etapa':'Nuevo proceso')?></h1><p><?=$limited?'Como usuario puede modificar únicamente las fechas. Cada cambio queda registrado.':'Complete la información. Los cambios de plazo requieren motivo y quedan en el historial.'?></p></div><a class="btn ghost" href="tasks.php">← Volver</a></div><?php if($error):?><div class="bad"><?=h($error)?></div><?php endif;?>
<form method="post" class="form-sheet"><input type="hidden" name="csrf" value="<?=h(csrf())?>">
<?php if(!$limited):?><div class="form-section"><h2>1. Identificación</h2><div class="form-grid"><label>ID / Código<input name="code" required value="<?=h($t['code']??'')?>"></label><label>Nivel<select name="level" id="level"><option value="PROCESO" <?=$requestedLevel==='PROCESO'?'selected':''?>>PROCESO</option><option value="ETAPA" <?=$requestedLevel==='ETAPA'?'selected':''?>>ETAPA</option></select></label><label id="parentBox">Proceso padre<select name="parent_code"><option value="">Seleccione</option><?php foreach($processes as $pr):?><option value="<?=h($pr['code'])?>" <?=$requestedParent===$pr['code']?'selected':''?>><?=h($pr['code'].' · '.$pr['task'])?></option><?php endforeach;?></select></label><label>Área / Unidad<select name="area"><option></option><?php foreach(catalog_values('area') as $x):?><option <?=($t['area']??'')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label class="span2">Proceso / Proyecto<input name="project" value="<?=h($t['project']??'')?>"></label><label class="span2">Etapa / Tarea<input name="task" required value="<?=h($t['task']??'')?>"></label></div></div>
<div class="form-section"><h2>2. Gestión</h2><div class="form-grid"><label>Responsable<input name="responsible" list="responsables" value="<?=h($t['responsible']??($_SESSION['name']??''))?>" placeholder="Seleccione o escriba"><datalist id="responsables"><?php foreach(catalog_values('responsible') as $x):?><option value="<?=h($x)?>"><?php endforeach;?></datalist></label><label>Prioridad<select name="priority"><option></option><?php foreach(catalog_values('priority') as $x):?><option <?=($t['priority']??'')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>Estado<select name="status"><option></option><?php foreach(catalog_values('status') as $x):?><option <?=($t['status']??'')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>Riesgo<select name="risk"><option></option><?php foreach(catalog_values('risk') as $x):?><option <?=($t['risk']??'')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label class="span2">Dependencia / Observación<textarea name="dependency" rows="3"><?=h($t['dependency']??'')?></textarea></label></div></div><?php endif;?>
<div class="form-section"><h2><?=$limited?'Modificar plazo':'3. Plazo'?></h2><div class="form-grid"><label>Fecha inicio<input type="date" name="start_date" value="<?=h($t['start_date']??'')?>"></label><label>Fecha término<input type="date" name="end_date" value="<?=h($t['end_date']??'')?>"></label><?php if($id):?><label class="span2">Motivo del cambio de fecha <span>*</span><textarea name="extension_reason" rows="3" placeholder="Ej.: Proveedor solicita ampliación de plazo; nueva fecha autorizada..."></textarea></label><?php endif;?></div><?php if($id):$ex=extension_info($t);?><p><b>Fecha término original:</b> <?=h($ex['orig']??'—')?><?php if($ex['extended']):?> · <span class="alert amarillo">PLAZO EXTENDIDO +<?=$ex['days']?> DÍAS</span><?php endif;?><?php if($ex['wasOverdue']):?> · <span class="alert rojo">FUERA DEL PLAZO ORIGINAL</span><?php endif;?></p><?php endif;?></div>
<?php if(!$limited):?><div class="form-section"><h2>4. Compra pública / seguimiento</h2><div class="form-grid"><label>Hito compra<select name="purchase_milestone"><option></option><?php foreach(catalog_values('milestone') as $x):?><option <?=($t['purchase_milestone']??'')===$x?'selected':''?>><?=h($x)?></option><?php endforeach;?></select></label><label>N° Requerimiento / Licitación / OC<input name="reference_no" value="<?=h($t['reference_no']??'')?>"></label><label>Monto<input type="number" step="0.01" name="amount" value="<?=h((string)($t['amount']??''))?>"></label><label>Proveedor<input name="provider" value="<?=h($t['provider']??'')?>"></label><label>Próximo hito<input name="next_milestone" list="hitos" value="<?=h($t['next_milestone']??'')?>" placeholder="Seleccione o escriba"><datalist id="hitos"><?php foreach(catalog_values('milestone') as $x):?><option value="<?=h($x)?>"><?php endforeach;?></datalist></label><label>Fecha próximo hito<input type="date" name="next_date" value="<?=h($t['next_date']??'')?>"></label></div></div><?php endif;?><div class="form-actions"><a class="btn ghost" href="tasks.php">Cancelar</a><button class="btn primary">Guardar</button></div></form>
<?php if($hist):?><section class="panel"><h2>Historial de cambios de plazo</h2><div class="table-scroll"><table class="excel-table"><thead><tr><th>Fecha cambio</th><th>Usuario</th><th>Inicio anterior</th><th>Inicio nuevo</th><th>Término anterior</th><th>Término nuevo</th><th>Motivo</th></tr></thead><tbody><?php foreach($hist as $h):?><tr><td><?=h($h['changed_at'])?></td><td><?=h($h['name']??'Usuario')?></td><td><?=h($h['old_start_date']??'—')?></td><td><?=h($h['new_start_date']??'—')?></td><td><?=h($h['old_end_date']??'—')?></td><td><?=h($h['new_end_date']??'—')?></td><td><?=h($h['reason']??'')?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><script>const level=document.getElementById('level'),box=document.getElementById('parentBox');if(level&&box){function t(){box.style.display=level.value==='ETAPA'?'flex':'none'}level.addEventListener('change',t);t();}</script><?php require 'footer.php';?>
